module.exports = /*#__PURE__*/JSON.parse('[{"id":"lich-nghi-le-quoc-khanh-2026","title":"Thông báo lịch nghỉ lễ Quốc khánh 02/09/2026","category":"Thông báo nội bộ","date":"2025-08-20","excerpt":"Thông tin lịch nghỉ lễ Quốc khánh, lịch trực vận hành và thời gian làm việc trở lại dành cho toàn thể nhân sự.","image":"/assets/news/nation-day-02092026.jpg","readingMinutes":2,"sections":[{"title":"Thông tin lịch nghỉ","paragraphs":["Thực hiện theo quy định của Nhà nước về chế độ nghỉ Lễ, Tết theo Bộ luật Lao động hiện hành.","Căn cứ theo hoạt động và tình hình thực tế của công ty, ban lãnh đạo Sonic Group quyết định thông báo lịch nghỉ lễ Quốc khánh 02/09/2026 để các phòng ban chủ động sắp xếp kế hoạch công việc, bàn giao các đầu việc đang vận hành và đảm bảo hoạt động chung của công ty."]},{"title":"Lịch nghỉ","paragraphs":["Thời gian nghỉ lễ: Thứ Tư, ngày 02/09/2026 và Thứ Năm, ngày 03/09/2026."]},{"title":"Phạm vi áp dụng","paragraphs":["Lịch nghỉ lễ áp dụng cho toàn thể nhân sự tại các chi nhánh của Sonic Group. Các phòng ban cần đảm bảo rằng các đầu việc quan trọng được bàn giao và cập nhật trạng thái trước kỳ nghỉ để tránh gián đoạn hoạt động."]},{"title":"Thời gian làm việc trở lại","paragraphs":["Toàn thể nhân sự trở lại làm việc bình thường từ Thứ Sáu, ngày 04/09/2026."]}]},{"id":"mo-rong-khong-gian-van-hanh-2026","title":"Dời địa điểm và mở rộng không gian vận hành tại chi nhánh Tôn Thất Tùng","category":"Thông báo công ty","date":"2026-06-01","excerpt":"Không gian mới giúp các đội Content, Commerce và Livestream phối hợp nhanh hơn trong cùng một nhịp sản xuất.","image":"/assets/news/change-location-01062026.jpg","readingMinutes":3,"sections":[{"title":"Thông tin thay đổi","paragraphs":["Sonic Group chính thức di dời địa điểm và mở rộng không gian vận hành tại chi nhánh Tôn Thất Tùng, tạo thêm khu vực làm việc tập trung cho các đội sản xuất nội dung, thương mại điện tử và livestream."]},{"title":"Không gian vận hành mới","paragraphs":["Thiết kế mới ưu tiên các cụm làm việc linh hoạt, khu vực trao đổi nhanh và không gian thử nghiệm nội dung. Mục tiêu là rút ngắn thời gian phối hợp giữa ý tưởng, sản xuất và đo lường hiệu quả."]},{"title":"Phối hợp giữa hai chi nhánh","paragraphs":["Các hoạt động tại hai chi nhánh vẫn được vận hành theo cùng một hệ thống dữ liệu và lịch làm việc chung, giúp nhân sự dễ dàng phối hợp khi dự án cần nhiều phòng ban tham gia."]}],"highlights":["Thêm khu vực làm việc cho đội ngũ tăng trưởng","Tăng khả năng phối hợp liên phòng ban","Bổ sung không gian thử nghiệm livestream và nội dung"]},{"id":"lich-nghi-le-304-015-2026","title":"Thông báo lịch nghỉ lễ 30/04 và 01/05 năm 2026","category":"Thông báo nội bộ","date":"2026-04-25","excerpt":"Thông tin lịch nghỉ lễ 30/04 và 01/05, lịch trực vận hành và thời gian làm việc trở lại dành cho toàn thể nhân sự.","image":"/assets/news/independence-day-30042026.jpg","readingMinutes":2,"sections":[{"title":"Thông tin lịch nghỉ","paragraphs":["Sonic Group thông báo lịch nghỉ lễ Ngày Chiến thắng 30/04 và Quốc tế Lao động 01/05 để các phòng ban chủ động sắp xếp kế hoạch công việc và bàn giao các đầu việc đang vận hành."]},{"title":"Lịch nghỉ","paragraphs":["Thời gian nghỉ lễ: Thứ Năm, ngày 30/04/2026 đến hết Chủ Nhật, ngày 03/05/2026."]},{"title":"Lịch trực và bàn giao","paragraphs":["Các đội có lịch trực hệ thống, chăm sóc khách hàng hoặc đối soát sẽ nhận lịch phân công riêng từ trưởng phòng. Mọi đầu việc cần được cập nhật trạng thái và bàn giao đầy đủ trước kỳ nghỉ."]},{"title":"Thời gian làm việc trở lại","paragraphs":["Toàn thể nhân sự trở lại làm việc bình thường từ Thứ Hai, ngày 04/05/2026."]}]}]');

